        data.extend([j.num("from"),j.num("to"),j.get("back").truth() as u8 as f64,if j.get("hub").truth(){self.name(j.get("hub")) as f64}else{-1.0},if j.get("externalKind").truth(){self.name(j.get("externalKind")) as f64}else{-1.0}]);data
